import{_ as n,o as r,c as t,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/akt-halbj-uebersicht-1.png",l="/bilder/schueler/akt-halbj-uebersicht-2.png",p=JSON.parse('{"title":"Leistungen über mehrere Lernabschnitte vergleichen","description":"","frontmatter":{"title":"Leistungen über mehrere Lernabschnitte vergleichen","source_pageid":546,"source_revision":5323},"headers":[],"relativePath":"schild3/schueler/uebersicht-schueler.md","filePath":"schild3/schueler/uebersicht-schueler.md"}'),a={name:"schild3/schueler/uebersicht-schueler.md"};function h(c,e,u,d,o,g){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="leistungen-uber-mehrere-lernabschnitte-vergleichen" tabindex="-1">Leistungen über mehrere Lernabschnitte vergleichen <a class="header-anchor" href="#leistungen-uber-mehrere-lernabschnitte-vergleichen" aria-label="Permalink to &quot;Leistungen über mehrere Lernabschnitte vergleichen&quot;">​</a></h1><p>Vergleichen Sie Fächer, Kurse und Endnoten über die vorhandenen Lernabschnitte. Die Übersicht bietet zusätzliche Anzeigen und einen Excel-Export.</p><p><a href="/bilder/schueler/akt-halbj-uebersicht-1.png"><img src="'+s+'" alt="Übersicht über eine ganze Schullaufbahn." loading="lazy"></a></p><p><em>Übersicht über eine ganze Schullaufbahn.</em></p><p>Der Reiter <em>Schüler</em> ➜ <em>Übersicht</em> zeigt für alle hinterlegten Lernabschnitte alle Fächer und Kurse mit ihren jeweiligen Endnoten.</p><p><a href="/bilder/schueler/akt-halbj-uebersicht-2.png"><img src="'+l+'" alt="Erklärung zu den verwendeten Farben." loading="lazy"></a></p><p><em>Erklärung zu den verwendeten Farben.</em></p><p>Das &quot;<strong>i</strong>&quot; hält eine Erklärung der verwendeten Farben bereit.</p><p>Hinter dem Symbol daneben verbirgt sich ein <strong>Export nach Excel</strong>. Bei einem Klick öffnet sich eine Vorschau, mit &quot;<strong>Speichern</strong>&quot; kann dann eine Datei gespeichert werden.</p><p><strong>Aktualisieren</strong> lädt die Leistungsdaten erneut, sollten diese zwischenzeitlich verändert worden sein.</p><p>Bei der <strong>Zusatz-Anzeige</strong> kann gewählt werden, ob zu jedem Fach/Kurs die <em>Kursart</em> oder <em>Fachlehrer</em> in der Tabelle eingeblendet werden sollen.</p><p><strong>Sekundarstufe</strong> lässt anwählen, ob nur die <em>Sek I</em>, nur die <em>Sek II</em> oder beide Sekundarstufen (Standardeinstellung) angezeigt werden soll.</p><p>Wenn Sie <strong>Sek II</strong> auswählen, erscheint eine weitere Auswahlliste. Dort legen Sie fest, ob die Leistungen als <strong>Noten</strong> oder <strong>Punkte</strong> angezeigt werden.</p><p>Aktivieren Sie <strong>Erste Spalte fixieren</strong>, damit die Fächer und Kurse beim seitlichen Verschieben der Tabelle sichtbar bleiben. Nur die folgenden Spalten werden dann verschoben.</p><p><strong>Nur Zeugnisfächer</strong> zeigt eben nur die Fächer an, die in der Facheinstellung als Zeugnisfächer markiert sind.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=%C3%9Cbersicht_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5323.</p>',17)])])}const m=n(a,[["render",h]]);export{p as __pageData,m as default};
